-- ==============================================================================
-- Migracao dos Lancamentos do Cartao Itau Fabiana para o Servidor de Producao
-- Total de lancamentos de cartao: 110
-- ==============================================================================

BEGIN;

-- 1. Cadastra ou atualiza o cartao na tabela credit_cards
VALUES ('Itaú Fabiana', 'Itaú', 13, 2, 'fabiana', TRUE)
ON CONFLICT (name) DO UPDATE
SET bank = EXCLUDED.bank,
    due_day = EXCLUDED.due_day,
    closing_day = EXCLUDED.closing_day,
    user_name = EXCLUDED.user_name,
    active = EXCLUDED.active;

-- 2. Insere os lancamentos vinculando dinamicamente ao card_id correspondente
DO $$
DECLARE
    v_card_id INT;
BEGIN
    SELECT id INTO v_card_id FROM credit_cards WHERE name = 'Itaú Fabiana' LIMIT 1;
    IF v_card_id IS NULL THEN
        RAISE EXCEPTION 'Cartao Itau Fabiana nao encontrado na tabela credit_cards!';
    END IF;

END $$;

COMMIT;
